#include <string>
#include <array>
#include <memory>
#include <cstdio>
#include <filesystem>

std::string get_ls_result(const std::string &dir_path) {
    if (!std::filesystem::exists(dir_path) || !std::filesystem::is_directory(dir_path)) {
        return "";
    }

    std::string command = "ls -l " + dir_path + " 2>/dev/null";
    std::array<char, 128> buffer;
    std::string result;
    std::shared_ptr<FILE> pipe(popen(command.c_str(), "r"), pclose);
    if (!pipe) {
        return "";
    }
    while (fgets(buffer.data(), buffer.size(), pipe.get()) != nullptr) {
        result += buffer.data();
    }
    return result;
}
```

### Explanation:
- **Input Validation**: The function checks if the provided path exists and is a directory using the `<filesystem>` library.
- **Command Execution**: Uses `popen` to execute the `ls -l` command and captures the output.
- **Error Handling**: Returns an empty string if the directory does not exist, is not a directory, or if any error occurs during command execution.

